PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,display_name TEXT,email TEXT,quota_bytes INTEGER NOT NULL DEFAULT 5242880,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS estates(id TEXT PRIMARY KEY,owner_user_id TEXT,name TEXT NOT NULL,country TEXT,region TEXT,locality TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS coffees(id TEXT PRIMARY KEY,owner_user_id TEXT,estate_id TEXT,name TEXT,variety TEXT,species TEXT,coffee_code TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(estate_id) REFERENCES estates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS lots(id TEXT PRIMARY KEY,owner_user_id TEXT,coffee_id TEXT,estate_id TEXT,lot_code TEXT,harvest_date TEXT,harvest_end_date TEXT,cherry_weight REAL,weight_unit TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(coffee_id) REFERENCES coffees(id) ON DELETE SET NULL,FOREIGN KEY(estate_id) REFERENCES estates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS process_templates(id TEXT PRIMARY KEY,owner_user_id TEXT,name TEXT NOT NULL,process_type TEXT,scope TEXT NOT NULL DEFAULT 'private' CHECK(scope IN ('koffykraft','private','shared')),source_template_id TEXT,current_version INTEGER NOT NULL DEFAULT 1,description TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(source_template_id) REFERENCES process_templates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS process_template_versions(id TEXT PRIMARY KEY,template_id TEXT NOT NULL,version INTEGER NOT NULL,name TEXT NOT NULL,process_type TEXT,description TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(template_id,version),FOREIGN KEY(template_id) REFERENCES process_templates(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS process_steps(id TEXT PRIMARY KEY,template_version_id TEXT NOT NULL,step_key TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,name TEXT NOT NULL,action_text TEXT,input_name TEXT,input_quantity REAL,input_unit TEXT,duration_minutes REAL,temperature_target REAL,temperature_unit TEXT DEFAULT 'C',ph_target REAL,moisture_target REAL,salinity_target REAL,target_text TEXT,observation_prompt TEXT,next_step_key TEXT,branch_json TEXT,config_json TEXT,UNIQUE(template_version_id,step_key),FOREIGN KEY(template_version_id) REFERENCES process_template_versions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS process_runs(id TEXT PRIMARY KEY,owner_user_id TEXT,template_version_id TEXT,lot_id TEXT,coffee_id TEXT,estate_id TEXT,name TEXT,status TEXT NOT NULL DEFAULT 'active',started_at TEXT,completed_at TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(template_version_id) REFERENCES process_template_versions(id) ON DELETE RESTRICT,FOREIGN KEY(lot_id) REFERENCES lots(id) ON DELETE SET NULL,FOREIGN KEY(coffee_id) REFERENCES coffees(id) ON DELETE SET NULL,FOREIGN KEY(estate_id) REFERENCES estates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,owner_user_id TEXT,process_run_id TEXT,step_key TEXT,observed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,kind TEXT NOT NULL,numeric_value REAL,text_value TEXT,unit TEXT,target_value REAL,target_min REAL,target_max REAL,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(process_run_id) REFERENCES process_runs(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS equipment(id TEXT PRIMARY KEY,owner_user_id TEXT,name TEXT NOT NULL,equipment_type TEXT,make TEXT,model TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS green_coffees(id TEXT PRIMARY KEY,owner_user_id TEXT,lot_id TEXT,process_run_id TEXT,coffee_id TEXT,moisture REAL,weight REAL,weight_unit TEXT DEFAULT 'g',storage_date TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(lot_id) REFERENCES lots(id) ON DELETE SET NULL,FOREIGN KEY(process_run_id) REFERENCES process_runs(id) ON DELETE SET NULL,FOREIGN KEY(coffee_id) REFERENCES coffees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS roast_profiles(id TEXT PRIMARY KEY,owner_user_id TEXT,name TEXT NOT NULL,coffee_id TEXT,equipment_id TEXT,target_text TEXT,config_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(coffee_id) REFERENCES coffees(id) ON DELETE SET NULL,FOREIGN KEY(equipment_id) REFERENCES equipment(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS roast_runs(id TEXT PRIMARY KEY,owner_user_id TEXT,green_coffee_id TEXT,coffee_id TEXT,estate_id TEXT,roast_profile_id TEXT,equipment_id TEXT,roast_no TEXT,roast_date TEXT,roast_type TEXT,green_weight REAL,roasted_weight REAL,moisture REAL,charge_temp REAL,target_color TEXT,final_color TEXT,total_seconds INTEGER,development_seconds INTEGER,dtr REAL,weight_loss REAL,notes TEXT,event_json TEXT,reading_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(green_coffee_id) REFERENCES green_coffees(id) ON DELETE SET NULL,FOREIGN KEY(coffee_id) REFERENCES coffees(id) ON DELETE SET NULL,FOREIGN KEY(estate_id) REFERENCES estates(id) ON DELETE SET NULL,FOREIGN KEY(roast_profile_id) REFERENCES roast_profiles(id) ON DELETE SET NULL,FOREIGN KEY(equipment_id) REFERENCES equipment(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS rest_runs(id TEXT PRIMARY KEY,owner_user_id TEXT,roast_run_id TEXT,name TEXT,started_at TEXT,target_end_at TEXT,actual_end_at TEXT,conditions TEXT,notes TEXT,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(roast_run_id) REFERENCES roast_runs(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS brew_recipes(id TEXT PRIMARY KEY,owner_user_id TEXT,name TEXT NOT NULL,method TEXT,config_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS brew_runs(id TEXT PRIMARY KEY,owner_user_id TEXT,recipe_id TEXT,roast_run_id TEXT,coffee_id TEXT,brewed_at TEXT,method TEXT,dose REAL,water REAL,water_temp REAL,grind TEXT,duration_seconds INTEGER,result_text TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(recipe_id) REFERENCES brew_recipes(id) ON DELETE SET NULL,FOREIGN KEY(roast_run_id) REFERENCES roast_runs(id) ON DELETE SET NULL,FOREIGN KEY(coffee_id) REFERENCES coffees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL,object_type TEXT NOT NULL,object_id TEXT NOT NULL,recipient_user_id TEXT,permission TEXT NOT NULL DEFAULT 'view',share_key TEXT UNIQUE,expires_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(recipient_user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY,owner_user_id TEXT,name TEXT NOT NULL,UNIQUE(owner_user_id,name),FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS object_tags(object_type TEXT NOT NULL,object_id TEXT NOT NULL,tag_id TEXT NOT NULL,PRIMARY KEY(object_type,object_id,tag_id),FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,owner_user_id TEXT,object_type TEXT NOT NULL,object_id TEXT NOT NULL,storage_key TEXT NOT NULL,media_type TEXT,byte_size INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_estates_owner_name ON estates(owner_user_id,name);
CREATE INDEX IF NOT EXISTS idx_coffees_owner_estate ON coffees(owner_user_id,estate_id);
CREATE INDEX IF NOT EXISTS idx_lots_owner_harvest ON lots(owner_user_id,harvest_date);
CREATE INDEX IF NOT EXISTS idx_templates_owner_type ON process_templates(owner_user_id,process_type);
CREATE INDEX IF NOT EXISTS idx_process_runs_owner_started ON process_runs(owner_user_id,started_at);
CREATE INDEX IF NOT EXISTS idx_observations_run_time ON observations(process_run_id,observed_at);
CREATE INDEX IF NOT EXISTS idx_roasts_owner_date ON roast_runs(owner_user_id,roast_date);
CREATE INDEX IF NOT EXISTS idx_roasts_estate_date ON roast_runs(estate_id,roast_date);
CREATE INDEX IF NOT EXISTS idx_roasts_coffee_date ON roast_runs(coffee_id,roast_date);
CREATE INDEX IF NOT EXISTS idx_roasts_type_date ON roast_runs(roast_type,roast_date);
CREATE INDEX IF NOT EXISTS idx_brews_owner_date ON brew_runs(owner_user_id,brewed_at);
CREATE INDEX IF NOT EXISTS idx_shares_object ON shares(object_type,object_id);
